 auto prep=Clock::now();std::vector<Vector4>mappts;if(mapterm)mappts=loadpoints(cfg["global_maps"][series.value("map_key",std::string((id=="fault"||id=="pass713")?"map1013":"map0105"))]);double mapread=elapsed(prep);Values estimate;size_t node=0;int64_t prev=t0;std::vector<std::pair<size_t,Cloud::Ptr>>history;std::map<size_t,int64_t>nt;json totals={{"series",id},{"E",experiment},{"initial_P",arr(P)},{"initial_pose",arr(initial.matrix())},{"source_count",records.size()},{"map_read_ms",mapread},{"lag_s",cfg["lag_s"]},{"initial_full_P_recovered",recovered},{"marginalized_nodes",0}};
 size_t wi=0;while(wi<wheels.size()&&wheels[wi].t<=t0)wi++;double geometrylin=0,geometryerr=0;size_t geomcalls=0;std::vector<double>stepms;int processed=0;size_t peaknodes=0;std::vector<boost::shared_ptr<Geometry>>activeGeom;
